#!/bin/bash
# shellcheck disable=all
set -veuo pipefail
code="$(grep -m 1 -B 999 -A 1 "ex""it" < "$0")"
cargo install --path "$(dirname "$(dirname "$0")")"
data="$(jeb encode-jeb85 split-80 join-lines < "$(which jeb)")"
echo -n "${code}"$'\n'"${data}"$'\n' > "$0"
exit
